    sh = max(r for r, c in stamp) + 1
    sw = max(c for r, c in stamp) + 1
    out = [row[:] for row in grid]

    for color in range(2, 10):
        if color == 4:
            continue
        remaining = {(r, c) for r in range(h) for c in range(w)
                     if grid[r][c] == color}

        # Group nearby fragments; a two-cell gap can still be part of one clue.
        while remaining:
            stack = [remaining.pop()]
            obj = set(stack)
            while stack:
                r, c = stack.pop()
                near = [(y, x) for y, x in remaining
                        if max(abs(y-r), abs(x-c)) <= 2]
                for p in near:
                    remaining.remove(p)
                    obj.add(p)
                    stack.append(p)

            minr = min(r for r, c in obj)
            maxr = max(r for r, c in obj)
            minc = min(c for r, c in obj)
            maxc = max(c for r, c in obj)
            choices = []
            for top in range(max(0, maxr-sh+1), min(minr, h-sh)+1):
                for left in range(max(0, maxc-sw+1), min(minc, w-sw)+1):
                    if all((r-top, c-left) in stamp for r, c in obj):
                        choices.append((top, left))
            if choices:
                top, left = choices[0]
                for dr, dc in stamp:
                    out[top+dr][left+dc] = color
    return out
